public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    String[] pathParts = path.split("/");
    String[] relativeParts = relativePath.split("/");
    int pathLength = pathParts.length;
    int relativeLength = relativeParts.length;

    // Handle absolute paths
    if (relativeParts[0].equals("")) {
        return relativeParts[0];
    }

    // Handle relative paths
    for (int i = 0; i < relativeLength; i++) {
        String relativePart = relativeParts[i];
        if (relativePart.equals("")) {
            continue;
        }
        if (relativePart.equals(".")) {
            continue;
        }
        if (relativePart.equals("..")) {
            if (pathLength == 0) {
                throw new IllegalArgumentException("Cannot apply relative path to root directory");
            }
            pathLength -= 1;
        } else {
            if (pathLength == 0) {
                throw new IllegalArgumentException("Invalid relative path");
            }
            pathParts[pathLength - 1] = relativePart;
        }
    }

    return String.join("/", pathParts);
}
